import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the AI workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-ai-workload-checklist.md","filePath":"frameworks/waf-ai-workload-checklist.md"}'),o={name:"frameworks/waf-ai-workload-checklist.md"};function i(s,t,n,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="waf-—-enumerated-source-for-the-ai-workload-assessment" tabindex="-1">WAF — enumerated source for the AI workload assessment <a class="header-anchor" href="#waf-—-enumerated-source-for-the-ai-workload-assessment" aria-label="Permalink to &quot;WAF — enumerated source for the AI workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01; re-verified and extended to all ten design areas 2026-11-24. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. A future <code>waf.ai.yaml</code> is written against this enumeration and nothing else, and every rule in it must cite an item number from the tables below.</p><h2 id="what-this-assessment-is" tabindex="-1">What this assessment is <a class="header-anchor" href="#what-this-assessment-is" aria-label="Permalink to &quot;What this assessment is&quot;">​</a></h2><p>Microsoft&#39;s <strong>Azure Well-Architected Framework AI workload assessment</strong> (<a href="https://learn.microsoft.com/en-us/assessments/ea306cce-c7fa-4a2b-89a6-bfefba6a9cf4" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/ea306cce-c7fa-4a2b-89a6-bfefba6a9cf4</a>) is one of Microsoft&#39;s per-workload specialised reviews (§14, item 4 of <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code>). Unlike Azure Local, AVD, and most other workloads, the AI workload is <strong>not organised by the five WAF pillars</strong> — it&#39;s organised into <strong>ten &quot;AI workload design areas&quot;</strong> described at <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/get-started#ai-workload-design-areas" target="_blank" rel="noreferrer">AI workloads on Azure</a>, and the assessment tool is built from questions &quot;based on the AI workload design areas.&quot;</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Design-area index</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/get-started" target="_blank" rel="noreferrer">AI workloads on Azure</a></td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework, AI workload guidance, current (<code>learn.microsoft.com/azure/well-architected/ai/</code>)</td></tr><tr><td>Extraction date</td><td>2026-08-01; re-verified 2026-11-24 (still ten design areas with the same names; Grounding data design gained a fifth recommendation)</td></tr><tr><td>Verification method</td><td>Each design-area article was fetched in full via the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool. Seven of the ten design areas publish a <strong>&quot;Recommendations&quot;</strong> summary table — a genuine, citable, Microsoft-authored checklist. Those seven tables are transcribed below in full.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The interactive assessment&#39;s question text and numbering are not published</strong>, exactly as with SMART and the Azure Local review. What this file enumerates instead is the <strong>&quot;Recommendations&quot;</strong> table that appears on seven of the ten design-area articles — each row is Microsoft&#39;s own bolded-recommendation-plus-description, which the assessment tool draws its questions from. The <code>WAF-AI-*</code> identifiers below are <strong>Scout&#39;s</strong>, not Microsoft&#39;s.</p><p><strong>Three design areas have no Microsoft &quot;Recommendations&quot; table.</strong> They are covered by <strong>Scout-derived</strong> items (see <a href="#scout-derived-items-for-the-three-areas-without-a-microsoft-table">Scout-derived items</a>), each read from the named article&#39;s sections and labelled as Scout&#39;s, not Microsoft&#39;s:</p><table tabindex="0"><thead><tr><th>Design area</th><th>Microsoft source shape</th></tr></thead><tbody><tr><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/data-platform" target="_blank" rel="noreferrer">Data platform</a></td><td>&quot;Technology options&quot; comparison tables and evaluation questions, not discrete checklist items.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/test" target="_blank" rel="noreferrer">Testing and evaluation</a></td><td>Narrative guidance and tooling lists.</td></tr><tr><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/personas" target="_blank" rel="noreferrer">Workload personas</a></td><td>Fetched 2026-11-24: persona definitions and their access needs, no table.</td></tr></tbody></table><p>The <a href="https://learn.microsoft.com/azure/well-architected/ai/architecture-pattern" target="_blank" rel="noreferrer">AI architecture pattern</a> page is not one of the ten design areas, but it carries concrete, checkable guidance, so Scout derives a few items from it as well (WAF-AI-ARCH).</p><p><strong>Shelf life.</strong> The AI workload guidance is one of the most actively developed corners of the WAF docs (new agentic-AI content lands frequently). Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration-—-35-microsoft-items-across-the-7-tabled-design-areas" tabindex="-1">The enumeration — 35 Microsoft items across the 7 tabled design areas <a class="header-anchor" href="#the-enumeration-—-35-microsoft-items-across-the-7-tabled-design-areas" aria-label="Permalink to &quot;The enumeration — 35 Microsoft items across the 7 tabled design areas&quot;">​</a></h2><h3 id="application-design-waf-ai-appd-—-6-items" tabindex="-1">Application design (WAF-AI-APPD) — 6 items <a class="header-anchor" href="#application-design-waf-ai-appd-—-6-items" aria-label="Permalink to &quot;Application design (WAF-AI-APPD) — 6 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/application-design" target="_blank" rel="noreferrer">Application design for AI workloads on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-APPD-01</td><td>Prioritize security and Responsible AI controls (provider safety systems, input/output filtering, rate limiting)</td><td>⚠️ Partial — <code>Security/DefenderAssessments</code> may surface generic findings; AI-specific content-safety config isn&#39;t collected</td></tr><tr><td>WAF-AI-APPD-02</td><td>Keep intelligence away from the client (back-end handles rate limiting, failover, AI logic)</td><td>❌ Unanswerable — an application-architecture pattern, not an ARM property</td></tr><tr><td>WAF-AI-APPD-03</td><td>Block direct access to data stores (route through an API/data-access abstraction)</td><td>❌ Unanswerable — code-level pattern</td></tr><tr><td>WAF-AI-APPD-04</td><td>Abstract models and tools behind standardized interfaces</td><td>❌ Unanswerable — code-level pattern</td></tr><tr><td>WAF-AI-APPD-05</td><td>Isolate behaviors and actions across client/intelligence/knowledge/tools layers</td><td>❌ Unanswerable — architecture pattern</td></tr><tr><td>WAF-AI-APPD-06</td><td>Prioritize prebuilt SaaS/PaaS solutions over custom builds</td><td>✅ <code>AI/OpenAIAccounts</code>, <code>AI/AppliedAIServices</code> presence indicates PaaS/SaaS adoption vs. <code>AI/MachineLearning</code> custom-build indicators</td></tr></tbody></table><h3 id="application-platform-waf-ai-appp-—-7-items" tabindex="-1">Application platform (WAF-AI-APPP) — 7 items <a class="header-anchor" href="#application-platform-waf-ai-appp-—-7-items" aria-label="Permalink to &quot;Application platform (WAF-AI-APPP) — 7 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/application-platform" target="_blank" rel="noreferrer">Application platform for AI workloads on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-APPP-01</td><td>Reuse existing tools before adopting a new one</td><td>❌ Organisational</td></tr><tr><td>WAF-AI-APPP-02</td><td>Consider compliance requirements for data and deployment regions</td><td>⚠️ Partial — resource <code>location</code> is collected on every <code>AI/*</code> collector; regulatory-fit judgement isn&#39;t automatable</td></tr><tr><td>WAF-AI-APPP-03</td><td>Minimize building — prefer PaaS/SaaS to reduce operational burden</td><td>✅ Same signal as WAF-AI-APPD-06</td></tr><tr><td>WAF-AI-APPP-04</td><td>Understand quotas and limits for the chosen PaaS/SaaS service</td><td>❌ Unanswerable — quota values aren&#39;t exposed via the ARG properties Scout reads</td></tr><tr><td>WAF-AI-APPP-05</td><td>Deploy related resources in the same region</td><td>✅ Cross-resource region comparison across <code>AI/*</code>, <code>Networking/*</code> collectors is a rule-authoring task on already-collected <code>location</code> fields</td></tr><tr><td>WAF-AI-APPP-06</td><td>Practice safe deployment — place APIs behind a gateway</td><td>⚠️ Partial — <code>Networking/PrivateEndpoint</code>, API Management collectors (if present) evidence a gateway; the practice itself isn&#39;t fully inferable</td></tr><tr><td>WAF-AI-APPP-07</td><td>Establish performance benchmarks through experimentation</td><td>❌ Unanswerable — a benchmarking exercise</td></tr></tbody></table><h3 id="training-data-design-waf-ai-train-—-5-items" tabindex="-1">Training data design (WAF-AI-TRAIN) — 5 items <a class="header-anchor" href="#training-data-design-waf-ai-train-—-5-items" aria-label="Permalink to &quot;Training data design (WAF-AI-TRAIN) — 5 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/training-data-design" target="_blank" rel="noreferrer">Design training data for AI workloads on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-TRAIN-01</td><td>Select data sources based on workload requirements (quality, balance, technique)</td><td>❌ Unanswerable — a data-science process decision</td></tr><tr><td>WAF-AI-TRAIN-02</td><td>Conduct data analysis (EDA) on collected data early</td><td>⚠️ Partial — <code>AI/MLComputes</code> presence suggests EDA tooling exists; whether it&#39;s used early is not collected</td></tr><tr><td>WAF-AI-TRAIN-03</td><td>Maintain data segmentation where security/technical requirements call for it</td><td>❌ Unanswerable — a data-pipeline design choice</td></tr><tr><td>WAF-AI-TRAIN-04</td><td>Preprocess data to remove noise and standardize formats</td><td>❌ Unanswerable — a pipeline implementation detail</td></tr><tr><td>WAF-AI-TRAIN-05</td><td>Avoid training on stale data — monitor for drift, define retraining triggers</td><td>⚠️ Partial — <code>AI/MLPipelines</code> presence indicates a retraining pipeline exists; drift-monitoring configuration isn&#39;t collected</td></tr></tbody></table><h3 id="grounding-data-design-waf-ai-ground-—-5-items" tabindex="-1">Grounding data design (WAF-AI-GROUND) — 5 items <a class="header-anchor" href="#grounding-data-design-waf-ai-ground-—-5-items" aria-label="Permalink to &quot;Grounding data design (WAF-AI-GROUND) — 5 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/grounding-data-design" target="_blank" rel="noreferrer">Grounding Data Design for AI Workloads on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-GROUND-01</td><td>Anticipate user queries when designing the grounding pipeline</td><td>❌ Unanswerable — a design-time decision</td></tr><tr><td>WAF-AI-GROUND-02</td><td>Externalize grounding data to a search index instead of querying the source system</td><td>✅ <code>AI/SearchServices</code>, <code>AI/SearchIndexes</code> presence evidences this</td></tr><tr><td>WAF-AI-GROUND-03</td><td>Develop a comprehensive ingestion strategy (dedup, standardize, rescope)</td><td>❌ Unanswerable — a pipeline implementation detail</td></tr><tr><td>WAF-AI-GROUND-04</td><td>Design the index for maximum relevancy (filtering, sorting, metadata)</td><td>⚠️ Partial — <code>AI/SearchIndexes</code> reports schema/field configuration where the API exposes it; relevancy tuning quality is not scorable</td></tr><tr><td>WAF-AI-GROUND-05</td><td>Update your index to prevent inferencing on stale data (added by Microsoft after 2026-08-01)</td><td>❌ Unanswerable — index refresh is data plane; the search services are attached as evidence</td></tr></tbody></table><h3 id="mlops-and-genaiops-waf-ai-mlops-—-4-items" tabindex="-1">MLOps and GenAIOps (WAF-AI-MLOPS) — 4 items <a class="header-anchor" href="#mlops-and-genaiops-waf-ai-mlops-—-4-items" aria-label="Permalink to &quot;MLOps and GenAIOps (WAF-AI-MLOPS) — 4 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/mlops-genaiops" target="_blank" rel="noreferrer">MLOps and GenAIOps for AI workloads on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-MLOPS-01</td><td>Design an efficient workload operations lifecycle (DataOps/MLOps/GenAIOps stages, tooling)</td><td>✅ Composite — <code>AI/MLPipelines</code>, <code>AI/MLEndpoints</code>, <code>AI/MLModels</code> together evidence lifecycle tooling is in place</td></tr><tr><td>WAF-AI-MLOPS-02</td><td>Automate everything in the build/test/validate/deploy cycle</td><td>⚠️ Partial — DevOps pipeline collectors (<code>DevOps/*</code>) can show CI/CD exists; whether AI-specific stages are automated is not distinguishable</td></tr><tr><td>WAF-AI-MLOPS-03</td><td>Use deployment pipelines for repeatable infrastructure and model promotion</td><td>⚠️ Partial — same as MLOPS-02</td></tr><tr><td>WAF-AI-MLOPS-04</td><td>Prevent drift and decay in models via structured maintenance</td><td>❌ Unanswerable — model-quality monitoring configuration isn&#39;t a collected property</td></tr></tbody></table><h3 id="workload-operations-waf-ai-ops-—-4-items" tabindex="-1">Workload operations (WAF-AI-OPS) — 4 items <a class="header-anchor" href="#workload-operations-waf-ai-ops-—-4-items" aria-label="Permalink to &quot;Workload operations (WAF-AI-OPS) — 4 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/operations" target="_blank" rel="noreferrer">AI workload operations on Azure</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-OPS-01</td><td>Monitor all aspects of the workload (component availability + quality metrics)</td><td>✅ <code>Monitor/DataCollectionRules</code>, <code>Monitor/MetricAlertRules</code> scoped to <code>AI/*</code> resources</td></tr><tr><td>WAF-AI-OPS-02</td><td>Apply safe deployment practices to AI components (blue-green, canary, side-by-side index updates)</td><td>❌ Unanswerable — a deployment-process practice</td></tr><tr><td>WAF-AI-OPS-03</td><td>Embrace DevOps practices — testing and automation in production</td><td>⚠️ Partial — <code>DevOps/*</code> collectors evidence pipeline existence generally</td></tr><tr><td>WAF-AI-OPS-04</td><td>Document progress — decisions, data sources, training history</td><td>❌ Organisational</td></tr></tbody></table><h3 id="responsible-ai-waf-ai-rai-—-4-items" tabindex="-1">Responsible AI (WAF-AI-RAI) — 4 items <a class="header-anchor" href="#responsible-ai-waf-ai-rai-—-4-items" aria-label="Permalink to &quot;Responsible AI (WAF-AI-RAI) — 4 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/ai/responsible-ai" target="_blank" rel="noreferrer">Responsible AI in Azure workloads</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AI-RAI-01</td><td>Develop policies enforcing responsible-AI practices at each lifecycle stage</td><td>❌ Organisational</td></tr><tr><td>WAF-AI-RAI-02</td><td>Protect user data — collect only what&#39;s necessary, apply technical controls</td><td>⚠️ Partial — <code>Security/Vault</code> evidences secret-handling infrastructure (vault configuration only); data-minimisation practice itself isn&#39;t scorable</td></tr><tr><td>WAF-AI-RAI-03</td><td>Keep AI decisions clear and understandable to users</td><td>❌ Unanswerable — a UX/transparency practice</td></tr><tr><td>WAF-AI-RAI-04</td><td>Implement agentic AI safeguards (auditability, RBAC, circuit breakers)</td><td>⚠️ Partial — <code>Identity/ConditionalAccess</code> and RBAC-assignment collectors (where present) evidence access control exists; circuit-breaker/auditability configuration is not collected</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Design area</th><th>Items</th><th>Answerable (✅)</th><th>Partial (⚠️)</th><th>Unanswerable (❌)</th></tr></thead><tbody><tr><td>Application design</td><td>6</td><td>1</td><td>1</td><td>4</td></tr><tr><td>Application platform</td><td>7</td><td>2</td><td>2</td><td>3</td></tr><tr><td>Training data design</td><td>5</td><td>0</td><td>2</td><td>3</td></tr><tr><td>Grounding data design</td><td>5</td><td>1</td><td>1</td><td>3</td></tr><tr><td>MLOps and GenAIOps</td><td>4</td><td>1</td><td>2</td><td>1</td></tr><tr><td>Workload operations</td><td>4</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Responsible AI</td><td>4</td><td>0</td><td>2</td><td>2</td></tr><tr><td><strong>Total, Microsoft-tabled (7 areas)</strong></td><td><strong>35</strong></td><td><strong>6</strong></td><td><strong>11</strong></td><td><strong>18</strong></td></tr><tr><td>Data platform (Scout-derived)</td><td>11</td><td>4</td><td>0</td><td>7</td></tr><tr><td>Testing and evaluation (Scout-derived)</td><td>8</td><td>0</td><td>0</td><td>8</td></tr><tr><td>Workload personas (Scout-derived)</td><td>4</td><td>0</td><td>0</td><td>4</td></tr><tr><td>AI architecture pattern (Scout-derived)</td><td>5</td><td>3</td><td>0</td><td>2</td></tr><tr><td><strong>All ten areas plus the pattern</strong></td><td><strong>63</strong></td><td><strong>13</strong></td><td><strong>11</strong></td><td><strong>39</strong></td></tr></tbody></table><p>(As enumerated 2026-08-01:) 6 of 34 enumerated items (18%) map cleanly to an existing collector — lower than Azure Local, because AI workload guidance is dominated by application-design and process practices (code architecture, data-science methodology, deployment process) that ARM/ARG inherently cannot see. 11 are partially answerable through existing <code>AI/*</code>, <code>Security/*</code>, <code>Monitor/*</code>, and <code>Identity/*</code> collectors. 17 are genuinely unanswerable — the highest proportion of any of the four checklists in this release, and an honest reflection of how much of &quot;AI workload well-architected&quot; is process and application-code discipline rather than infrastructure configuration.</p><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>A future <code>waf.ai.yaml</code> should cite <code>WAF-AI-*</code> item numbers. Given the low automatable fraction, this rule file should expect to carry more <code>manual: true</code> rows than any of the other three workload checklists in this release, and the report should say so rather than implying full coverage.</p><h2 id="scout-derived-items-for-the-three-areas-without-a-microsoft-table" tabindex="-1">Scout-derived items for the three areas without a Microsoft table <a class="header-anchor" href="#scout-derived-items-for-the-three-areas-without-a-microsoft-table" aria-label="Permalink to &quot;Scout-derived items for the three areas without a Microsoft table&quot;">​</a></h2><p>These items are <strong>Scout&#39;s reading of Microsoft&#39;s articles</strong>, not Microsoft checklist rows. Automated items (✅) run only when the relevant resources exist (the rule is gated), so an estate without AI resources reports them Not assessed rather than failed. Fields marked † were added to the assessment collection for these rules on 2026-11-24 (<code>id</code>, <code>location</code>, <code>disableLocalAuth</code> on AI accounts; <code>publicAccess</code>, <code>disableLocalAuth</code>, <code>replicaCount</code> on search services; <code>isolationMode</code> on ML workspaces).</p><h3 id="data-platform-waf-ai-data-—-11-items" tabindex="-1">Data platform (WAF-AI-DATA) — 11 items <a class="header-anchor" href="#data-platform-waf-ai-data-—-11-items" aria-label="Permalink to &quot;Data platform (WAF-AI-DATA) — 11 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/azure/well-architected/ai/data-platform" target="_blank" rel="noreferrer">Data platform for AI workloads</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-AI-DATA-01</td><td>A separate vector store is justified, or the source store&#39;s built-in vector search serves the workload</td><td>❌ Manual — Cosmos DB accounts attached</td></tr><tr><td>WAF-AI-DATA-02</td><td>The aggregation store handles multiple formats and data versioning</td><td>❌ Manual — Databricks workspaces attached</td></tr><tr><td>WAF-AI-DATA-03</td><td>Data lifecycle management is configured on AI data stores</td><td>❌ Manual — storage accounts attached</td></tr><tr><td>WAF-AI-DATA-04</td><td>Data governance and cataloguing are in place (Microsoft Purview)</td><td>✅ Purview account exists (gated on AI accounts)</td></tr><tr><td>WAF-AI-DATA-05</td><td>Data pipelines are not reachable from the public internet</td><td>✅ Data factories with public network access (estate-wide)</td></tr><tr><td>WAF-AI-DATA-06</td><td>Data residency and sovereignty requirements are met</td><td>❌ Manual — AI accounts with region † attached</td></tr><tr><td>WAF-AI-DATA-07</td><td>Search indexes run on an SLA tier with at least two replicas</td><td>✅ Free tier or replicaCount † below 2</td></tr><tr><td>WAF-AI-DATA-08</td><td>Search indexes are private and use Entra ID authentication</td><td>✅ Search services with public network access †</td></tr><tr><td>WAF-AI-DATA-09</td><td>Grounding results are security-trimmed per user</td><td>❌ Manual — data plane</td></tr><tr><td>WAF-AI-DATA-10</td><td>A feature store holds reusable training features (if the workload trains models)</td><td>❌ Manual — feature stores attached</td></tr><tr><td>WAF-AI-DATA-11</td><td>Development and production data environments are separated</td><td>❌ Manual</td></tr></tbody></table><h3 id="testing-and-evaluation-waf-ai-test-—-8-items" tabindex="-1">Testing and evaluation (WAF-AI-TEST) — 8 items <a class="header-anchor" href="#testing-and-evaluation-waf-ai-test-—-8-items" aria-label="Permalink to &quot;Testing and evaluation (WAF-AI-TEST) — 8 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/azure/well-architected/ai/test" target="_blank" rel="noreferrer">Test and evaluate AI workloads</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-AI-TEST-01</td><td>Quality metrics are baselined and used as release gates</td><td>❌ Manual</td></tr><tr><td>WAF-AI-TEST-02</td><td>A representative golden evaluation dataset is maintained</td><td>❌ Manual</td></tr><tr><td>WAF-AI-TEST-03</td><td>Agentic workflows are validated end to end (intent, tool calls, task adherence, tool failure)</td><td>❌ Manual</td></tr><tr><td>WAF-AI-TEST-04</td><td>Jailbreak, red-team and content-safety tests run</td><td>❌ Manual — Content Safety accounts attached</td></tr><tr><td>WAF-AI-TEST-05</td><td>Inference endpoints are tested for function, load and failure</td><td>❌ Manual</td></tr><tr><td>WAF-AI-TEST-06</td><td>The grounding pipeline is tested (schema, freshness, index load, access control)</td><td>❌ Manual — search services attached</td></tr><tr><td>WAF-AI-TEST-07</td><td>Training, evaluation and test datasets are separate, with leakage checks</td><td>❌ Manual</td></tr><tr><td>WAF-AI-TEST-08</td><td>Model decay is detected automatically</td><td>❌ Manual — ML workspaces attached</td></tr></tbody></table><h3 id="workload-personas-waf-ai-persona-—-4-items" tabindex="-1">Workload personas (WAF-AI-PERSONA) — 4 items <a class="header-anchor" href="#workload-personas-waf-ai-persona-—-4-items" aria-label="Permalink to &quot;Workload personas (WAF-AI-PERSONA) — 4 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/azure/well-architected/ai/personas" target="_blank" rel="noreferrer">Workload personas</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-AI-PERSONA-01</td><td>Personas are defined with their processes, skills and component access</td><td>❌ Manual</td></tr><tr><td>WAF-AI-PERSONA-02</td><td>Personas map to least-privilege roles per environment</td><td>❌ Manual — role assignments attached</td></tr><tr><td>WAF-AI-PERSONA-03</td><td>Agents have their own identities, just-in-time permissions and an audit trail</td><td>❌ Manual — managed identities attached</td></tr><tr><td>WAF-AI-PERSONA-04</td><td>Persona skill gaps are identified and the design adjusted</td><td>❌ Manual</td></tr></tbody></table><h3 id="ai-architecture-pattern-waf-ai-arch-—-5-items" tabindex="-1">AI architecture pattern (WAF-AI-ARCH) — 5 items <a class="header-anchor" href="#ai-architecture-pattern-waf-ai-arch-—-5-items" aria-label="Permalink to &quot;AI architecture pattern (WAF-AI-ARCH) — 5 items&quot;">​</a></h3><p>Source: <a href="https://learn.microsoft.com/azure/well-architected/ai/architecture-pattern" target="_blank" rel="noreferrer">Azure architecture pattern for AI workloads</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-AI-ARCH-01</td><td>Machine learning workspaces are not publicly reachable</td><td>✅ ML workspaces with public network access</td></tr><tr><td>WAF-AI-ARCH-02</td><td>The training platform is network-isolated (managed virtual network)</td><td>✅ ML workspaces whose isolationMode † is not a managed network</td></tr><tr><td>WAF-AI-ARCH-03</td><td>High-risk agent actions need human approval</td><td>❌ Manual</td></tr><tr><td>WAF-AI-ARCH-04</td><td>The model registry is a governance gate before production</td><td>❌ Manual</td></tr><tr><td>WAF-AI-ARCH-05</td><td>AI service accounts require Entra ID authentication (local keys disabled)</td><td>✅ AI accounts with disableLocalAuth † not true</td></tr></tbody></table><h2 id="changes-found-on-re-verification-2026-11-24" tabindex="-1">Changes found on re-verification (2026-11-24) <a class="header-anchor" href="#changes-found-on-re-verification-2026-11-24" aria-label="Permalink to &quot;Changes found on re-verification (2026-11-24)&quot;">​</a></h2><ul><li>Microsoft&#39;s current product names are <strong>Microsoft Foundry</strong>, <strong>Azure OpenAI in Foundry Models</strong> and <strong>Foundry Tools</strong> (formerly Azure AI services / Cognitive Services). Azure AI Search is unchanged.</li><li>Several recommendations were reworded (APPD-01 adds identity-bound rate limits and token caps; APPD-03 adds propagating user and tenant context; APPD-05 now describes five layers including inferencing; RAI-04 is now &quot;Implement responsible practices for agentic AI systems&quot;). The items above keep Scout&#39;s IDs; the intent of each is unchanged.</li><li><code>CAF-AI-04</code> (in the <code>Assess: AI</code> category assessment) always reported Unknown because AI account IDs were never collected. They are now.</li></ul>',56)])])}const p=e(o,[["render",i]]);export{A as __pageData,p as default};
